/* KOREA Phase 1: offline-friendly, static, dependency-free interactive history prototype. */
'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cl='')=>`<svg class="icon ${cl}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const getStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('korea-v1-'+key))??fallback}catch{return fallback}};
const setStore=(key,value)=>{try{localStorage.setItem('korea-v1-'+key,JSON.stringify(value))}catch{}};
const defaultSettings={mode:'deep',font:18,width:720,autoplay:true};
const state={architecture:null,manifest:null,all:[],nodes:new Map(),chapters:new Map(),parts:new Map(),samples:new Map(),expanded:new Set(),searchOpen:false,searchQuery:'',searchSelected:0,mobileMenu:false,showSettings:false,bookmarks:getStore('bookmarks',[]),history:getStore('history',[]),progress:getStore('progress',{}),settings:{...defaultSettings,...getStore('settings',{})},readingToken:0,activeArticle:null,loader:null,toastTimer:null,detours:[],readingN:0,readerChain:[],activeMode:'deep',pendingRestore:null};
const app=$('#app');
function label(id){const n=state.nodes.get(id)||state.chapters.get(id)||state.parts.get(id);return n?.title||id}
function wordNum(n){return new Intl.NumberFormat('en-US').format(n)}
function pathFor(id){return `#/history/${id}`}
function jump(hash){const h=hash.startsWith('#')?hash:'#'+hash;if(location.hash===h){renderRoute();window.scrollTo(0,0)}else location.hash=h}
function markActiveNav(id){const r=routeInfo();return r.kind==='part'&&r.id===id||r.kind==='reader'&&r.id.split('.')[0]===id?' current':''}
function eraLabel(id){const p=id.split('.')[0];return state.parts.get(p)?.title||''}
function chapterLabel(id){return state.chapters.get(id.split('.').slice(0,2).join('.'))?.title||''}
function sampleInfo(id){return state.samples.get(id)}
function coreNode(id){const n=state.nodes.get(id);if(n)return {type:'subchapter',node:n,parent:id};const m=id.match(/^([IVX]+\.\d+\.\d+)\.(\d+)(?:\.(\d+))?$/);if(!m||!state.nodes.has(m[1])||Number(m[2])<1||Number(m[2])>10||m[3]&&(Number(m[3])<1||Number(m[3])>10))return null;return {type:m[3]?'terminal':'section',node:state.nodes.get(m[1]),parent:m[1],section:m[2],terminal:m[3]};}
function renderHeader(){return `<header class="app-header"><div class="header-brand"><button class="menu-button" data-action="toggle-menu" aria-label="Open historical navigation">${icon('menu','lg')}</button><a href="#/" class="wordmark" aria-label="KOREA homepage">KOREA<span>AN ENDLESS HISTORY</span></a></div><nav class="top-nav" aria-label="Primary navigation"><button data-route="#/" class="${location.hash==='#/'||!location.hash?'active':''}">Discover</button><button data-route="#/eras" class="${location.hash.startsWith('#/part')||location.hash==='#/eras'?'active':''}">The eras</button><button data-route="#/saved" class="${location.hash==='#/saved'?'active':''}">My library</button></nav><div class="header-spacer"></div><button class="header-search" data-action="search" aria-label="Search 1000 historical topics">${icon('search')}<span>Search the archive</span><kbd class="kbd">/</kbd></button><button class="header-icon-btn" data-route="#/saved" title="Bookmarked history" aria-label="Bookmarked history">${icon('bookmark')}</button></header>`}
function renderEraList(){return state.architecture.parts.map(p=>`<button class="side-era${markActiveNav(p.id)}" data-route="#/part/${p.id}"><span class="roman">${p.id}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.period)}</small></span></button>`).join('')}
function renderSidebar(){return `<aside class="sidebar" aria-label="Era navigation"><p class="side-overline">Find your way</p><button class="side-feature${location.hash==='#/'?' current':''}" data-route="#/">${icon('compass')} Discover history</button><button class="side-feature" data-action="random">${icon('spark')} Surprise me</button><button class="side-feature${location.hash==='#/saved'?' current':''}" data-route="#/saved">${icon('bookmark')} Your bookmarks <span style="margin-left:auto;color:#a34d37">${state.bookmarks.length}</span></button><div class="side-divider"></div><p class="side-overline">Ten historical eras</p>${renderEraList()}<div class="sidebar-note"><strong>THE ARCHIVE, PHASE 1</strong><br>1,000 authentic canonical topic addresses<br>${state.manifest.count} narrative samples available<br>Everything else is marked planned.</div></aside>`}
function renderMobileMenu(){return state.mobileMenu?`<div class="mobile-shade visible" data-action="toggle-menu"><div class="mobile-drawer" role="dialog" aria-modal="true" aria-label="Historical navigation"><button class="mobile-close" data-action="toggle-menu">${icon('close')} &nbsp; Close navigation</button><p class="side-overline">Find your way</p><button class="side-feature" data-route="#/">${icon('compass')} Discover</button><button class="side-feature" data-route="#/saved">${icon('bookmark')} My library</button><p class="side-overline" style="margin-top:25px">Ten eras</p>${renderEraList()}</div></div>`:''}
function renderMobileBottom(){const isReader=location.hash.startsWith('#/history');return `<nav class="mobile-bottom" aria-label="Mobile navigation"><button data-route="#/" class="${location.hash==='#/'?'active':''}">${icon('home')}Home</button><button data-route="#/eras" class="${location.hash==='#/eras'||location.hash.startsWith('#/part')?'active':''}">${icon('tree')}Eras</button><button data-action="search">${icon('search')}Search</button><button data-route="#/saved" class="${location.hash==='#/saved'?'active':''}">${icon('bookmark')}Saved</button></nav>`}
function layout(content){app.innerHTML=renderHeader()+`<div class="layout">${renderSidebar()}<main class="main" id="main-content">${content}</main></div>`+renderMobileBottom()+renderMobileMenu()+(state.searchOpen?renderSearch():'');if(state.searchOpen){$('#searchInput')?.focus();renderSearchResults()}document.documentElement.style.setProperty('--reader-width',state.settings.width+'px');document.documentElement.style.setProperty('--reader-font',state.settings.font+'px')}
function storyCard(info){return `<button class="story-card" data-route="${pathFor(info.id)}"><span class="story-id">${esc(info.id)} / ${esc(eraLabel(info.id).toUpperCase())}</span><h3>${esc(info.title)}</h3><p>${esc(info.description)}</p><span class="bottom"><span>${wordNum(info.wordCount)} words · ${info.blocks} passages</span>${icon('arrow')}</span></button>`}
function renderHome(){const p=state.architecture.parts;const article=state.manifest.articles;const featured=[article[3],article[2],article[4]];return `<div class="page"><section class="home-hero"><div class="hero-copy"><div class="hero-label">THE HISTORY UNIVERSE &nbsp; / &nbsp; EST. 2026</div><h1 class="hero-title">Every age has<br><em>another story.</em></h1><p class="hero-desc">Walk through the world of Korea, from its deepest beginnings to the present day. Take the short route, follow a curiosity, or keep reading as long as you like.</p><div class="hero-actions"><button class="btn-primary" data-route="${pathFor(article[0].id)}">Begin at the beginning ${icon('arrow')}</button><button class="btn-outline" data-action="random">Surprise me ${icon('spark')}</button></div><div class="hero-metric"><span><b>10</b> historical eras</span><span><b>1,000</b> authentic topics</span><span><b>∞</b> room to explore</span></div></div><div class="hero-side-label">THE PENINSULA / THROUGH TIME</div></section><div class="home-body"><div class="section-head"><div><span class="eyebrow">OPEN A DOOR</span><h2>Where will you begin?</h2></div><button class="text-action" data-action="random">A different story ${icon('arrow','sm')}</button></div><div class="story-grid">${featured.map(storyCard).join('')}</div><section class="home-eras"><div class="section-head"><div><span class="eyebrow">THE LONG VIEW</span><h2>Ten eras. One unfolding history.</h2></div><span class="planned">Explore the full architecture</span></div><div class="era-grid">${p.map(e=>`<button class="era-card" data-route="#/part/${e.id}"><span class="era-num">${e.id}</span><span><h3>${esc(e.title)}</h3><small>${esc(e.period)}</small></span>${icon('arrow')}</button>`).join('')}</div></section><div class="reassurance">${icon('book','lg')}<div><h3>There is no wrong place to start.</h3><p>Each topic leads somewhere else. You can always return to where you left off, and unfinished parts of the archive are clearly marked.</p></div></div></div></div>`}
function renderEras(){return `<div class="page list-page"><div class="list-intro"><span class="eyebrow">CHOOSE YOUR CENTURY</span><h1>The long story,<br>in ten eras.</h1><p>Open any era to see all ten original Chapters and their hundred canonical Subchapters. The full framework is real; only a small portion has demonstration reading content in this prototype.</p></div><div class="era-grid" style="margin-top:35px">${state.architecture.parts.map(e=>`<button class="era-card" data-route="#/part/${e.id}"><span class="era-num">${e.id}</span><span><h3>${esc(e.title)}</h3><small>${esc(e.period)}</small></span>${icon('arrow')}</button>`).join('')}</div></div>`}
function chapterGrid(ch){return `<div class="subchapter-grid">${ch.subchapters.map(s=>`<button class="subchapter-btn" data-route="${pathFor(s.id)}"><span>${esc(s.id.split('.').at(-1).padStart(2,'0'))}</span><span>${esc(s.title)}<br>${sampleInfo(s.id)?'<b class="label-published">Read sample →</b>':'<small class="planned">Planned</small>'}</span>${icon('chevron')}</button>`).join('')}</div>`}
function renderPart(id){const p=state.parts.get(id);if(!p)return renderMissing();const cur=state.expanded;const n=p.chapters.flatMap(c=>c.subchapters).filter(s=>sampleInfo(s.id)).length;return `<div class="page list-page"><div class="list-intro"><div class="chapter-kicker"><span class="marker">${p.id}</span><span>ERA ${state.architecture.parts.indexOf(p)+1} OF 10 &nbsp; / &nbsp; ${esc(p.period)}</span></div><h1>${esc(p.title)}</h1><p>${esc(p.description)} Explore the original ten Chapters and their hundred canonical Subchapters. ${n} ${n===1?'topic has':'topics have'} a demonstration narrative; all other destinations are reserved for future writing.</p></div><div class="chapter-list">${p.chapters.map((ch,i)=>`<div class="chapter-row"><button class="chapter-heading" data-action="chapter" data-id="${ch.id}" aria-expanded="${cur.has(ch.id)}"><span class="ch-no">${String(i+1).padStart(2,'0')} / 10</span><span class="ch-title">${esc(ch.title)}</span><span class="ch-count">10 subjects</span>${icon(cur.has(ch.id)?'close':'chevron')}</button>${cur.has(ch.id)?chapterGrid(ch):''}</div>`).join('')}</div></div>`}
function renderSaved(){const ids=state.bookmarks.filter(x=>state.nodes.has(x));const recent=state.history.filter(x=>state.nodes.has(x)&&!ids.includes(x)).slice(0,8);return `<div class="page saved-page"><span class="eyebrow">YOUR PRIVATE READING SPACE</span><h1>My library</h1><p style="color:var(--muted);line-height:1.85">Your reading places and bookmarks are saved in this browser only. No sign-in, no account and no server.</p><div class="section-head" style="margin-top:40px"><div><span class="eyebrow">KEPT FOR LATER</span><h2>Bookmarks (${ids.length})</h2></div></div>${ids.length?`<div class="saved-list">${ids.map(id=>renderSavedRow(id)).join('')}</div>`:`<div class="empty-message">${icon('bookmark','lg')}<h3>No saved paths yet.</h3><p>When a story catches your attention, select the bookmark in the reader. It will appear here for your next visit.</p><button class="button-quiet" data-route="#/">Find a story ${icon('arrow','sm')}</button></div>`}<div class="section-head" style="margin-top:48px"><div><span class="eyebrow">RETURN TO THE PATH</span><h2>Recently visited</h2></div><button class="text-action" data-action="clear-history">Clear history</button></div>${recent.length?`<div class="saved-list">${recent.map(renderSavedRow).join('')}</div>`:`<div class="empty-message"><p>Visited history topics will appear here automatically.</p></div>`}</div>`}
function renderSavedRow(id){const info=sampleInfo(id);return `<button class="saved-row" data-route="${pathFor(id)}">${icon('book','lg')}<span><strong>${esc(label(id))}</strong><small>${esc(id)} · ${esc(eraLabel(id))}${info?` · ${wordNum(info.wordCount)} words`:''}</small></span>${icon('arrow')}</button>`}
function readerCrumbs(id){const p=id.split('.');const nodes=[p[0],p.slice(0,2).join('.'),p.slice(0,3).join('.')];return `<nav class="crumbs" aria-label="Breadcrumbs"><button data-route="#/">Discover</button>${icon('chevron')}${nodes.map((x,i)=>`<button data-route="${i===0?'#/part/'+x:i===1?'#/part/'+p[0]:pathFor(x)}" title="${esc(label(x))}">${esc(i===0?x:i===1?label(x):x)}</button>${i!==2?icon('chevron'):''}`).join('')}${id!==nodes[2]?icon('chevron')+`<span>${esc(id)}</span>`:''}</nav>`}
function virtualPlanList(parent,curSection){let str='<div class="plan-box"><span class="eyebrow">ARCHITECTURE / RESERVED</span><h3>100 planned destinations under this subject</h3><p>The v1.1 source fixes the ten-Section and hundred-terminal addresses beneath this Subchapter, but their actual Section titles have not been authored in the supplied canonical files. They are displayed as reserved IDs, not invented historical topics.</p><div class="plan-list">';for(let i=1;i<=10;i++){let id=parent+'.'+i;str+=`<button class="plan-node" data-route="${pathFor(id)}"><span>${id}</span>${curSection===String(i)?'Selected':`Planned section ${i}`}${icon('chevron','sm')}</button>`}str+='</div></div>';return str}
function renderPlanned(id,entry){const parent=entry.parent;const selected=entry.type==='section'?id:entry.type==='terminal'?parent+'.'+entry.section:undefined;let title=entry.type==='subchapter'?entry.node.title:`${entry.type==='terminal'?'Terminal subsection':'Section'} ${id}`;return `<div class="reader-shell"><div class="reader-main"><div class="reader-inner">${readerCrumbs(parent)}<div class="reader-hero"><span class="eyebrow">${esc(id)} &nbsp; / &nbsp; PLANNED</span><h1 class="reader-title">${esc(title)}</h1><p class="reader-desc">${entry.type==='subchapter'?'A place in the original canonical architecture, waiting for its narrative.':'A reserved location below the canonical Subchapter '+parent+'.'}</p><div class="reader-meta"><span>${esc(eraLabel(parent))}</span><span>Not published</span></div></div><div class="empty-message"><h3>There’s more history to write.</h3><p>This is a real structural destination, but it has no sample reading content yet. Try a neighboring topic with a reading sample, or explore the larger Part.</p><button class="btn-light" data-route="#/part/${parent.split('.')[0]}">Browse this era ${icon('arrow','sm')}</button></div>${entry.type==='terminal'?`<div class="plan-box"><p>Parent section: <button class="text-action" data-route="${pathFor(selected)}">${selected} ${icon('arrow','sm')}</button></p></div>`:virtualPlanList(parent,entry.section)}${relatedSection(parent)}</div></div><aside class="reader-rail">${railRelated(parent)}</aside></div>`}
function nextSample(id){const list=state.manifest.articles;let x=list.findIndex(a=>a.id===id);return list[(x+1)%list.length]}
function relatedNodes(id){const n=state.nodes.get(id);if(!n)return[];let neighbors=n.related.filter(x=>state.nodes.has(x)&&x!==id);let ch=state.chapters.get(id.split('.').slice(0,2).join('.'));if(ch){for(let s of ch.subchapters){if(s.id!==id&&!neighbors.includes(s.id))neighbors.push(s.id)}}const authored=[...neighbors.filter(x=>sampleInfo(x)),...state.manifest.articles.map(a=>a.id).filter(x=>x!==id&&!neighbors.includes(x))];return authored.slice(0,4)}
function relatedSection(id){return `<section style="margin-top:43px"><div class="section-head"><div><span class="eyebrow">TAKE A SIDE PATH</span><h2>You might also explore</h2></div></div><div class="story-grid">${relatedNodes(id).slice(0,3).map(x=>sampleInfo(x)?storyCard(sampleInfo(x)):`<button class="story-card" data-route="${pathFor(x)}"><span class="story-id">${x} / PLANNED</span><h3>${esc(label(x))}</h3><p>A related topic in the original master architecture.</p><span class="bottom">Reserved canonical ID ${icon('arrow')}</span></button>`).join('')}</div></section>`}
function railRelated(id){return `<div class="rail-group"><p class="rail-title">Explore nearby</p>${relatedNodes(id).map(x=>`<button class="rail-related" data-action="detour" data-id="${x}"><small>${x} · ${sampleInfo(x)?'READ SAMPLE':'PLANNED'}</small><strong>${esc(label(x))}</strong></button>`).join('')}</div><div class="rail-note">Take a detour and you can return to the exact reading position you left.</div>`}
function renderReader(id){const entry=coreNode(id);if(!entry)return renderMissing();if(entry.type!=='subchapter'||!sampleInfo(id))return renderPlanned(id,entry);const info=sampleInfo(id);const mode=state.settings.mode;const saved=state.bookmarks.includes(id);const back=state.detours.length?`<button class="reader-action" data-action="return-detour">${icon('back')}<span class="action-caption">Return to previous path</span></button>`:'';return `<div class="reader-shell"><article class="reader-main"><div class="reader-inner">${readerCrumbs(id)}<header class="reader-hero"><div class="eyebrow">${esc(info.kicker)} &nbsp; / &nbsp; ${id}</div><h1 class="reader-title">${esc(info.title)}</h1><p class="reader-desc">${esc(info.description)}</p><div class="reader-meta"><span>${esc(eraLabel(id))}</span><span>${esc(chapterLabel(id))}</span><span><strong>${wordNum(info.wordCount)}</strong> sample words</span><span>${info.blocks} passages</span>${(state.progress[id]?.scrollY||0)>350?`<button class="text-action" data-action="resume" data-id="${id}">Resume where you left off ${icon('arrow','sm')}</button>`:''}</div><div class="editorial-disclosure">Prototype editorial narrative. These are demonstration texts, not research-verified scholarly entries. Unpublished canonical destinations are marked planned.</div></header><div class="reader-tools" id="readerTools"><div class="mode-tabs" role="group" aria-label="Reading depth"><button data-action="mode" data-mode="overview" class="${mode==='overview'?'active':''}" aria-pressed="${mode==='overview'}">Overview</button><button data-action="mode" data-mode="deep" class="${mode==='deep'?'active':''}" aria-pressed="${mode==='deep'}">Deep dive</button><button data-action="mode" data-mode="endless" class="${mode==='endless'?'active':''}" aria-pressed="${mode==='endless'}">Endless</button></div><div class="reader-actions">${back}<button class="reader-action${saved?' saved':''}" data-action="bookmark" data-id="${id}" aria-label="${saved?'Remove bookmark':'Save bookmark'}" title="${saved?'Remove bookmark':'Save bookmark'}">${icon('bookmark')}<span class="action-caption">${saved?'Saved':'Save'}</span></button><button class="reader-action" data-action="settings" aria-label="Reader appearance" title="Reading settings">${icon('settings')}</button></div><div class="read-progress" id="readProgress" style="width:0"></div></div>${state.showSettings?renderReaderSettings():''}<section class="reader-body" id="readerBody" aria-label="Historical reading content">${mode==='overview'?renderOverview(info):`<div class="load-more" id="loadState" aria-live="polite">Opening the first passage…</div>`}</section></div></article><aside class="reader-rail"><div class="rail-group"><p class="rail-title">Within this story</p>${info.chunks.map((x,i)=>`<button class="rail-toc" data-action="go-chunk" data-idx="${i}">${String(i+1).padStart(2,'0')} &nbsp; ${esc(x.title)}</button>`).join('')}</div>${railRelated(id)}<p class="rail-title" style="margin-top:25px">Reading note</p><div class="rail-note">${mode==='endless'?'More segments load as you read. After the final passage, the next sample begins.':'Switch to Endless to continue through linked stories.'}</div></aside></div>`}
function renderReaderSettings(){return `<div class="reader-toolbar-sub"><div class="choice"><label for="fontSizer">Text size</label><input id="fontSizer" type="range" min="15" max="23" step="1" value="${state.settings.font}" data-control="font"/><span id="fontVal">${state.settings.font}px</span></div><div class="choice"><label>Line width</label><button data-action="width" data-value="610" class="${state.settings.width===610?'active':''}">Narrow</button><button data-action="width" data-value="720" class="${state.settings.width===720?'active':''}">Normal</button><button data-action="width" data-value="850" class="${state.settings.width===850?'active':''}">Wide</button></div></div>`}
function renderOverview(info){return `<div class="body-section"><span class="section-number">AT A GLANCE</span><h2>One story, many directions</h2><div class="article-prose"><p>${esc(info.description)} This introductory view points you to the central ideas without requiring a long reading commitment. Choose a passage below, or switch to Deep dive for the complete narrative.</p></div><div class="overview-topics">${info.chunks.map((c,i)=>`<button class="overview-link" data-action="overview-chunk" data-idx="${i}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(c.title)}</strong>${icon('arrow')}</button>`).join('')}</div></div>${relatedSection(info.id)}${virtualPlanList(info.id)}`}
function renderMissing(){return `<div class="list-page"><span class="eyebrow">NOT FOUND</span><h1>That path doesn’t exist.</h1><p>The archive only accepts IDs present in the canonical 1,000-Subchapter structure and its reserved 10-by-10 descendants.</p><button class="btn-light" data-route="#/">Return to Discover ${icon('arrow')}</button></div>`}
function routeInfo(){const route=(location.hash||'#/').replace(/^#/,'');if(route==='/')return{kind:'home'};if(route==='/eras')return{kind:'eras'};if(route==='/saved')return{kind:'saved'};if(route.startsWith('/part/'))return{kind:'part',id:route.split('/')[2]};if(route.startsWith('/history/'))return{kind:'reader',id:decodeURIComponent(route.slice(9))};return{kind:'missing'}}
async function renderRoute({keepScroll=false}={}){state.readingToken++;const token=state.readingToken;const route=routeInfo();if(!keepScroll)window.scrollTo({top:0,behavior:'instant'});if(route.kind==='home')layout(renderHome());else if(route.kind==='eras')layout(renderEras());else if(route.kind==='saved')layout(renderSaved());else if(route.kind==='part')layout(renderPart(route.id));else if(route.kind==='reader'){
 const entry=coreNode(route.id);if(entry){if(!state.history.includes(route.id)){state.history.unshift(route.id)}else{state.history=[route.id,...state.history.filter(x=>x!==route.id)]};state.history=state.history.slice(0,30);setStore('history',state.history)}
 state.activeArticle=route.id;state.activeMode=state.settings.mode;state.readingN=0;state.readerChain=[route.id];layout(renderReader(route.id));if(sampleInfo(route.id)&&state.activeMode!=='overview')await loadNextChunk(token);
 const restoring=state.pendingRestore;
 if(restoring?.id===route.id&&state.activeMode!=='overview'){
   state.pendingRestore=null;
   let attempts=0;
   while(state.readingN<Math.min(restoring.blocks||1,sampleInfo(route.id).blocks)&&attempts++<15&&token===state.readingToken){await loadNextChunk(token)}
   if(token===state.readingToken)requestAnimationFrame(()=>window.scrollTo({top:restoring.y,behavior:'instant'}));
 }
 updateProgress();
 }else layout(renderMissing());}
function renderBlock(b,id,number){return `<section class="body-section" id="${esc(b.id)}" data-blockid="${esc(b.id)}"><span class="section-number">PASSAGE ${String(number).padStart(2,'0')}</span><h2>${esc(b.title)}</h2><div class="article-prose">${b.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></section>`}
async function loadNextChunk(token=state.readingToken){if(token!==state.readingToken||state.loader)return;const body=$('#readerBody');if(!body)return;const id=state.readerChain.at(-1),info=sampleInfo(id);if(!info)return;let current=state.readingN;
 if(current>=info.chunks.length){if(state.settings.mode==='endless'&&state.readerChain.length<state.manifest.articles.length){const next=nextSample(id);if(state.readerChain.includes(next.id))return renderReadingEnd(id);state.readerChain.push(next.id);state.readingN=0;body.insertAdjacentHTML('beforeend',`<section class="segment-transition"><span class="eyebrow">A NEW STORY / THE CURATED TRAIL</span><h2>${esc(next.title)}</h2><p>${esc(next.description)}</p><button class="text-action" data-route="${pathFor(next.id)}">Open as its own page ${icon('arrow','sm')}</button></section>`);return loadNextChunk(token)}return renderReadingEnd(id)}
 const chunk=info.chunks[current];state.loader=chunk.id;$('#loadState')?.remove();try{const response=await fetch(chunk.path);if(!response.ok)throw new Error('HTTP '+response.status);const b=await response.json();if(token!==state.readingToken)return;body.insertAdjacentHTML('beforeend',renderBlock(b,id,current+1));state.readingN++;
 if(state.readingN===2&&state.readerChain.length===1){const suggestion=relatedNodes(id).find(other=>sampleInfo(other));if(suggestion){body.insertAdjacentHTML('beforeend',`<aside class="inline-trail" aria-label="Explore a related historical path"><div><span class="eyebrow">A SIDE PATH</span><p>Curious about another era? Leave this story for a moment and return to your place afterward.</p></div><button data-action="detour" data-id="${suggestion}">${esc(label(suggestion))} ${icon('arrow','sm')}</button></aside>`)}}
 const more=state.readingN<info.chunks.length||state.settings.mode==='endless'&&state.readerChain.length<state.manifest.articles.length;if(more){body.insertAdjacentHTML('beforeend',`<div class="load-more" id="loadState"><button data-action="load-more">${state.settings.mode==='endless'?'Continue reading':'Read next passage'} ${icon('arrow','sm')}</button><div id="loadSentinel" style="height:2px"></div></div>`);if(state.settings.mode==='endless')observeSentinel(token)}else{renderReadingEnd(id)}updateProgress();}catch(e){if(token===state.readingToken){body.insertAdjacentHTML('beforeend',`<div class="empty-message" id="loadState"><h3>Passage could not be loaded.</h3><p>${esc(e.message)}. Run this prototype using a local HTTP server, not file://.</p><button class="button-quiet" data-action="load-more">Try again</button></div>`)}}finally{state.loader=null}}
function observeSentinel(token){state.observer?.disconnect();const target=$('#loadSentinel');if(!target)return;state.observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting&&token===state.readingToken&&state.settings.mode==='endless'){state.observer.disconnect();loadNextChunk(token)}},{rootMargin:'0px 0px 150px 0px'});state.observer.observe(target)}
function renderReadingEnd(id){$('#loadState')?.remove();const body=$('#readerBody');if(!body||$('#endSlab'))return;const n=nextSample(id);body.insertAdjacentHTML('beforeend',`<section class="end-slab" id="endSlab"><span class="eyebrow">YOU'VE REACHED THE LAST PASSAGE</span><h3>There is always another direction.</h3><p>This demonstration has a finite selection of ${state.manifest.count} stories. The larger planned universe retains 100,000 reserved historical destinations.</p><div class="next-actions"><button class="btn-primary" data-route="${pathFor(n.id)}">Next story ${icon('arrow','sm')}</button><button class="btn-light" data-route="#/eras">Explore all eras</button></div></section>${relatedSection(state.activeArticle)}${virtualPlanList(state.activeArticle)}`)}
function updateProgress(persist=false){const bar=$('#readProgress');if(!bar)return;const pageH=Math.max(1,document.documentElement.scrollHeight-innerHeight);const raw=Math.min(100,Math.max(0,Math.round((scrollY/pageH)*100)));bar.style.width=raw+'%';if(persist&&scrollY>100&&state.activeArticle&&sampleInfo(state.activeArticle)){const old=state.progress[state.activeArticle]||{};if(Math.abs((old.scrollY||0)-scrollY)>180){state.progress[state.activeArticle]={scrollY:Math.round(scrollY),date:new Date().toISOString(),lastBlock:state.readingN};setStore('progress',state.progress)}}}
async function goChunk(i){if(state.settings.mode==='overview'){state.settings.mode='deep';persistSettings();await renderRoute();}let n=0;while(state.readingN<=i&&n++<12){await loadNextChunk();if(state.loader)break}const id=state.activeArticle+':b'+String(i+1).padStart(2,'0');document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});}
function persistSettings(){setStore('settings',state.settings)}
function notify(msg){$('.toast')?.remove();const div=document.createElement('div');div.className='toast';div.setAttribute('role','status');div.textContent=msg;document.body.appendChild(div);clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>div.remove(),2600)}
function toggleBookmark(id){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[id,...state.bookmarks];setStore('bookmarks',state.bookmarks);const was=state.bookmarks.includes(id);notify(was?'Saved to your library':'Bookmark removed');const btn=$('[data-action=bookmark]');if(btn){btn.classList.toggle('saved',was);btn.setAttribute('aria-label',was?'Remove bookmark':'Save bookmark');btn.innerHTML=icon('bookmark')+`<span class="action-caption">${was?'Saved':'Save'}</span>`}const count=$('.sidebar .side-feature span');if(count)count.textContent=state.bookmarks.length}

function searchItems(){const q=state.searchQuery.trim().toLocaleLowerCase();const all=state.all;const matches=q?all.map(e=>({...e,score:(e.id.toLowerCase()===q?25:0)+(e.id.toLowerCase().startsWith(q)?10:0)+(e.title.toLocaleLowerCase().includes(q)?3:0)+(e.title.toLocaleLowerCase().startsWith(q)?10:0)+(sampleInfo(e.id)?1:0)})).filter(e=>e.score>0).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id,undefined,{numeric:true})):state.manifest.articles.map(a=>({...a,score:10}));return matches.slice(0,50)}
function renderSearch(){return `<div class="search-overlay" data-action="close-search"><div class="search-dialog" role="dialog" aria-modal="true" aria-label="Search historical topics"><div class="search-input-wrap">${icon('search','lg')}<input id="searchInput" type="search" placeholder="Search kingdoms, people, periods, IDs…" value="${esc(state.searchQuery)}" aria-label="Search the archive" autocomplete="off"/><button data-action="close-search" aria-label="Close search">${icon('close')}</button></div><div class="search-results" id="searchResults"></div><div class="search-hint">1,000 canonical topics searchable · ↑↓ select · Enter open · Esc close</div></div></div>`}
function renderSearchResults(){const el=$('#searchResults');if(!el)return;const list=searchItems();if(!list.length){el.innerHTML='<div class="dialog-blank">No matching canonical topics. Try a different term.</div>';return}state.searchSelected=Math.max(0,Math.min(list.length-1,state.searchSelected));el.innerHTML=list.map((e,i)=>`<button class="${state.searchSelected===i?'selected':''}" data-route="${pathFor(e.id)}" data-search-index="${i}"><span style="min-width:64px;color:var(--rust);font-size:11px">${e.id}</span><span style="flex:1"><strong>${esc(e.title)}</strong><small>${esc(eraLabel(e.id))} · ${sampleInfo(e.id)?'Read sample available':'Planned'}</small></span>${icon('arrow','sm')}</button>`).join('')}
function openSearch(){if(state.searchOpen)return;state.searchOpen=true;state.searchQuery='';state.searchSelected=0;document.body.insertAdjacentHTML('beforeend',renderSearch());renderSearchResults();$('#searchInput')?.focus()}
function closeSearch(){state.searchOpen=false;$('.search-overlay')?.remove();$('[data-action=search]')?.focus()}
function toggleMenu(){state.mobileMenu=!state.mobileMenu;$('.mobile-shade')?.remove();if(state.mobileMenu)document.body.insertAdjacentHTML('beforeend',renderMobileMenu())}
function setDetour(id){if(!state.nodes.has(id))return;state.detours.push({id:state.activeArticle,y:Math.round(scrollY),blocks:state.readingN,mode:state.settings.mode});jump(pathFor(id))}
function returnDetour(){const d=state.detours.pop();if(!d)return;state.settings.mode=d.mode;persistSettings();state.pendingRestore={id:d.id,y:d.y,blocks:d.blocks};jump(pathFor(d.id))}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action],[data-route]');if(!button)return;if(button.classList.contains('search-overlay')&&event.target.closest('.search-dialog'))return;if(button.classList.contains('mobile-shade')&&event.target.closest('.mobile-drawer'))return;
 if(button.hasAttribute('data-route')){event.preventDefault();state.mobileMenu=false;$('.mobile-shade')?.remove();state.searchOpen=false;$('.search-overlay')?.remove();state.expanded=new Set();jump(button.dataset.route);return}
 const act=button.dataset.action;switch(act){case 'toggle-menu':toggleMenu();break;case 'search':openSearch();break;case 'close-search':closeSearch();break;case 'random':{const list=state.manifest.articles;jump(pathFor(list[Math.floor(Math.random()*list.length)].id));break}case 'chapter':{let id=button.dataset.id;state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);renderRoute({keepScroll:true});break}case 'bookmark':toggleBookmark(button.dataset.id);break;case 'clear-history':state.history=[];setStore('history',[]);renderRoute({keepScroll:true});break;case 'mode':state.settings.mode=button.dataset.mode;persistSettings();renderRoute();break;case 'settings':{state.showSettings=!state.showSettings;$('.reader-toolbar-sub')?.remove();if(state.showSettings)$('#readerTools')?.insertAdjacentHTML('afterend',renderReaderSettings());break}case 'width':{state.settings.width=Number(button.dataset.value);persistSettings();document.documentElement.style.setProperty('--reader-width',state.settings.width+'px');$$('[data-action=width]').forEach(b=>b.classList.toggle('active',Number(b.dataset.value)===state.settings.width));break}case 'load-more':await loadNextChunk();break;case 'go-chunk':case 'overview-chunk':await goChunk(Number(button.dataset.idx));break;case 'detour':setDetour(button.dataset.id);break;case 'return-detour':returnDetour();break;case 'resume':{const id=button.dataset.id;const progress=state.progress[id];if(progress){state.pendingRestore={id,y:progress.scrollY,blocks:progress.lastBlock};await renderRoute();}break}}}
);
document.addEventListener('input',event=>{if(event.target.id==='searchInput'){state.searchQuery=event.target.value;state.searchSelected=0;renderSearchResults()}if(event.target.id==='fontSizer'){state.settings.font=Number(event.target.value);document.documentElement.style.setProperty('--reader-font',state.settings.font+'px');$('#fontVal').textContent=state.settings.font+'px';persistSettings()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.searchOpen){e.preventDefault();closeSearch()}else if(state.mobileMenu){toggleMenu()}}if(e.key==='/'&&!state.searchOpen&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();return}if(state.searchOpen){const items=searchItems();if(e.key==='ArrowDown'){e.preventDefault();state.searchSelected=Math.min(items.length-1,state.searchSelected+1);renderSearchResults();$('.search-results .selected')?.scrollIntoView({block:'nearest'})}else if(e.key==='ArrowUp'){e.preventDefault();state.searchSelected=Math.max(0,state.searchSelected-1);renderSearchResults();$('.search-results .selected')?.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&items.length){e.preventDefault();state.searchOpen=false;$('.search-overlay')?.remove();jump(pathFor(items[state.searchSelected].id))}}});
let scrollThrottle=false;window.addEventListener('scroll',()=>{if(!scrollThrottle){scrollThrottle=true;requestAnimationFrame(()=>{updateProgress(true);scrollThrottle=false})}},{passive:true});
window.addEventListener('hashchange',()=>{state.searchOpen=false;state.mobileMenu=false;$('.search-overlay')?.remove();$('.mobile-shade')?.remove();state.observer?.disconnect();state.loader=null;state.showSettings=false;state.expanded=new Set();const r=routeInfo();if(r.kind==='part'&&state.parts.has(r.id))state.expanded.add(state.parts.get(r.id).chapters[0].id);renderRoute()});
(async function init(){try{const [a,m]=await Promise.all([fetch('./data/architecture.json'),fetch('./data/content-manifest.json')]);if(!a.ok||!m.ok)throw new Error('Data files could not be loaded');state.architecture=await a.json();state.manifest=await m.json();for(const article of state.manifest.articles)state.samples.set(article.id,article);for(const p of state.architecture.parts){state.parts.set(p.id,p);for(const ch of p.chapters){state.chapters.set(ch.id,ch);for(const sub of ch.subchapters){state.nodes.set(sub.id,sub);state.all.push(sub)}}}if(state.parts.size!==10||state.chapters.size!==100||state.nodes.size!==1000)throw new Error('Canonical source structure does not match 10/100/1000');const initial=routeInfo();if(initial.kind==='part'&&state.parts.has(initial.id))state.expanded.add(state.parts.get(initial.id).chapters[0].id);await renderRoute()}catch(err){app.innerHTML=`<main class="empty-message" style="margin:10vh auto;max-width:600px"><h1>KOREA could not open the archive.</h1><p>${esc(err.message)}. Start a local HTTP server from the project directory using <code>python3 -m http.server 8000</code> and open <code>http://localhost:8000/</code>.</p></main>`}})();
